    auto origin = inShape->GetOriginShape();

    // 获取维度数与最后一维长度（作为约简维）
    int64_t dimNum = origin.GetDimNum();
    int64_t inner = origin.GetDim(dimNum - 1);
    uint32_t totalLength = origin.GetShapeSize();
    uint32_t innerU = static_cast<uint32_t>(inner);
    uint32_t totalOuter = static_cast<uint32_t>(totalLength / innerU);

    // 简化：每次处理1行
    uint32_t tileRows = 1;

    // 设置并保存tiling信息
    tiling.set_totalOuter(totalOuter);
    tiling.set_inner(innerU);
    tiling.set_tileRows(tileRows);

    // 设置Block数
    context->SetBlockDim(8);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // 无需workspace
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
